import '../../../models/daily_nutrition.dart';
import '../../../models/health_metric.dart';
import '../../../models/recovery_summary.dart';
import '../../../models/workout_history.dart';

/// Decisions generated by the AI Decision Engine across training, nutrition, and recovery.
class AIDecisionReport {
  final List<String> trainingDecisions;
  final List<String> nutritionDecisions;
  final List<String> recoveryDecisions;
  final double
  volumeMultiplier; // 1.0 = normal, 0.8 = deload -20%, 1.1 = overload +10%
  final int recommendedCalorieAdjustment; // e.g. +250 or -150
  final bool recommendRest;
  final DateTime generatedAt;

  const AIDecisionReport({
    required this.trainingDecisions,
    required this.nutritionDecisions,
    required this.recoveryDecisions,
    this.volumeMultiplier = 1.0,
    this.recommendedCalorieAdjustment = 0,
    this.recommendRest = false,
    required this.generatedAt,
  });

  factory AIDecisionReport.initial() {
    return AIDecisionReport(
      trainingDecisions: const ['Continue planned workout split.'],
      nutritionDecisions: const ['Meet daily calorie and protein targets.'],
      recoveryDecisions: const ['Maintain 7-9 hours of restful sleep.'],
      volumeMultiplier: 1.0,
      recommendedCalorieAdjustment: 0,
      recommendRest: false,
      generatedAt: DateTime.now(),
    );
  }
}

/// Central AI Decision Engine evaluating multi-domain athlete biometric data
/// to prescribe autonomous training volume adjustments, nutritional tweaks, and recovery protocols.
class AIDecisionEngine {
  static AIDecisionEngine? _instance;
  static AIDecisionEngine get instance => _instance ??= AIDecisionEngine();

  /// Evaluates training, nutrition, and recovery biometrics to output an actionable decision report.
  AIDecisionReport evaluate({
    required List<WorkoutHistory> workoutHistory,
    required RecoverySummary recovery,
    required DailyNutrition? todayNutrition,
    required List<HealthMetric> recentHealthMetrics,
    String goal = 'hypertrophy',
  }) {
    final trainingDecisions = <String>[];
    final nutritionDecisions = <String>[];
    final recoveryDecisions = <String>[];
    double volumeMultiplier = 1.0;
    int calorieAdjustment = 0;
    bool recommendRest = false;

    // ------------------------------------------------------------
    // 1. RECOVERY BIOMETRIC EVALUATION
    // ------------------------------------------------------------
    final readiness = recovery.score;
    final sleepHours = recovery.sleepHours;
    final sleepText = (sleepHours == null || sleepHours <= 0)
        ? 'sleep not recorded'
        : 'sleep ${sleepHours.toStringAsFixed(1)}h';

    if (!recovery.isMeasured) {
      // No recorded sleep, HRV or heart rate: no recovery verdict, no change.
      volumeMultiplier = 1.0;
      recoveryDecisions.add(
        'Recovery cannot be assessed: no sleep, HRV or heart-rate data is recorded, so training volume is not adjusted for recovery.',
      );
    } else if (readiness < 45 ||
        (sleepHours != null && sleepHours > 0 && sleepHours < 5.5)) {
      recommendRest = true;
      volumeMultiplier = 0.6;
      recoveryDecisions.add(
        'Recovery readiness is critical ($readiness%), $sleepText. Rest day recommended.',
      );
      trainingDecisions.add(
        'Postpone heavy compound lifts. Substitute with light active recovery mobility session.',
      );
    } else if (readiness < 65 ||
        (sleepHours != null && sleepHours > 0 && sleepHours < 6.5)) {
      volumeMultiplier = 0.8;
      recoveryDecisions.add(
        'Moderate recovery readiness ($readiness%). Prioritize sleep and hydration.',
      );
      trainingDecisions.add(
        'Reduce today\'s training volume by 20% to prevent fatigue accumulation.',
      );
    } else {
      volumeMultiplier = 1.0;
      recoveryDecisions.add(
        'Recovery score is strong ($readiness%). Full readiness for high-intensity training.',
      );
      trainingDecisions.add(
        'Prime readiness for progressive overload: increase working weight by 2.5kg on top sets.',
      );
    }

    // ------------------------------------------------------------
    // 2. TRAINING PROGRESSION & FATIGUE EVALUATION
    // ------------------------------------------------------------
    if (workoutHistory.isNotEmpty) {
      final lastSession = workoutHistory.first;
      final daysSinceLast = DateTime.now()
          .difference(lastSession.dateCompleted)
          .inDays;

      if (daysSinceLast == 0 && !recommendRest) {
        trainingDecisions.add(
          'Workout completed today (${lastSession.workoutName}). Focus on muscle protein synthesis.',
        );
      } else if (daysSinceLast >= 4) {
        trainingDecisions.add(
          '4+ days since last workout. Resume scheduled split with a standard warm-up.',
        );
      }
    }

    // ------------------------------------------------------------
    // 3. NUTRITION & MACRONUTRIENT EVALUATION
    // ------------------------------------------------------------
    if (todayNutrition != null) {
      final totals = todayNutrition.totalsConsumed;
      final currentProtein = totals.protein;
      final targetProtein = todayNutrition.targets.protein;
      final proteinDelta = targetProtein - currentProtein;

      if (!totals.proteinComplete && proteinDelta > 25.0) {
        // The logged amount is a minimum, so it can neither show a shortfall
        // nor a good day: say what is known and what is missing.
        nutritionDecisions.add(
          'Protein total is incomplete: at least ${currentProtein.toInt()}g logged of ${targetProtein.toInt()}g, and some foods have no protein value. Add the missing values to check your target.',
        );
      } else if (proteinDelta > 25.0) {
        nutritionDecisions.add(
          'Protein intake is low today (${currentProtein.toInt()}g / ${targetProtein.toInt()}g). Prioritize a high-protein meal.',
        );
      } else {
        nutritionDecisions.add(
          'Protein intake is on track (${currentProtein.toInt()}g / ${targetProtein.toInt()}g).',
        );
      }

      if (goal.toLowerCase().contains('gain') ||
          goal.toLowerCase().contains('hypertrophy') ||
          goal.toLowerCase().contains('bulk')) {
        calorieAdjustment = 250;
        nutritionDecisions.add(
          'Increase calories by +250 kcal for lean muscle building and recovery support.',
        );
      } else if (goal.toLowerCase().contains('loss') ||
          goal.toLowerCase().contains('cut')) {
        calorieAdjustment = -200;
        nutritionDecisions.add(
          'Maintain moderate caloric deficit (-200 kcal) for lean body composition.',
        );
      }
    } else {
      nutritionDecisions.add(
        'Log meals today to unlock personalized nutritional coaching.',
      );
    }

    return AIDecisionReport(
      trainingDecisions: trainingDecisions,
      nutritionDecisions: nutritionDecisions,
      recoveryDecisions: recoveryDecisions,
      volumeMultiplier: volumeMultiplier,
      recommendedCalorieAdjustment: calorieAdjustment,
      recommendRest: recommendRest,
      generatedAt: DateTime.now(),
    );
  }
}
